begin;
create extension if not exists pgtap with schema extensions;
select plan(24);

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values ('00000000-0000-0000-0000-000000003901','00000000-0000-0000-0000-000000000000','authenticated','authenticated','canonical-pipeline@example.invalid','','{}','{}',now(),now());
insert into public.resource_registry(id,display_name,lifecycle_state,editorial_status) values
 ('00000000-0000-0000-0000-000000003911','Working Gear','active','approved'),
 ('00000000-0000-0000-0000-000000003912','neXup','active','approved'),
 ('00000000-0000-0000-0000-000000003913','Protected Transition House','active','approved'),
 ('00000000-0000-0000-0000-000000003914','Reuse Clinic','active','approved');

select ok(not has_function_privilege('anon','public.persist_canonical_authoritative_location_evidence_v1(uuid,uuid,text,text,text,text,uuid)','execute'),'anon cannot persist canonical research evidence');
select ok(not has_function_privilege('authenticated','public.bind_existing_canonical_authoritative_evidence_v1(uuid,uuid,uuid,uuid,uuid)','execute'),'ordinary users cannot rebind evidence');
select ok(has_function_privilege('service_role','public.supersede_canonical_authoritative_address_v1(uuid,uuid,uuid,uuid,text,uuid)','execute'),'service role can perform controlled correction');

select set_config('role','service_role',true);
select public.begin_canonical_authoritative_research_run('00000000-0000-0000-0000-000000003902',4,'00000000-0000-0000-0000-000000003901');
select public.reserve_canonical_authoritative_research_item('00000000-0000-0000-0000-000000003902','00000000-0000-0000-0000-000000003911','00000000-0000-0000-0000-000000003901');
insert into public.resource_fact_claims(id,resource_id,field_name,proposed_value,risk,recommendation,confidence,engine_version,status,claim_fingerprint)
values('00000000-0000-0000-0000-000000003921','00000000-0000-0000-0000-000000003911','location_occupancy','"520 Powell Street, Vancouver, BC"','medium','human_review','high','fixture','observed',repeat('a',64));
select is(public.persist_canonical_authoritative_location_evidence_v1('00000000-0000-0000-0000-000000003902','00000000-0000-0000-0000-000000003911','https://workinggear.ca/contact','working-gear-contact','Working Gear is now at 475 Main St, Unit 228, Vancouver.','475 Main St, Unit 228, Vancouver, BC','00000000-0000-0000-0000-000000003901')->>'outcome','authoritative_current_address_confirmed','authoritative first-party program-at-site evidence is persisted');
select is((select outcome from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),'confirmed','persistence completes the reserved run item');
select is((select source_authority from public.resource_fact_evidence where claim_id<>( '00000000-0000-0000-0000-000000003921'::uuid) and source_url='https://workinggear.ca/contact'),90,'source authority is derived from server URL policy');
select is(public.supersede_canonical_authoritative_address_v1('00000000-0000-0000-0000-000000003911','00000000-0000-0000-0000-000000003921',(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),(select evidence_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),'authoritative_move','00000000-0000-0000-0000-000000003901')->>'outcome','authoritative_address_corrected','authoritative move supersedes only the prior claim');
select is((select status from public.resource_fact_claims where id='00000000-0000-0000-0000-000000003921'),'superseded','historical Working Gear claim remains as superseded history');
select is((select count(*)::integer from public.canonical_authoritative_address_corrections where resource_id='00000000-0000-0000-0000-000000003911'),1,'correction provenance is append-only');
select is((select count(*)::integer from public.resource_locations where resource_id='00000000-0000-0000-0000-000000003911'),0,'correction does not create locations');
select ok(not has_function_privilege('anon','public.persist_canonical_bc_geocoder_evidence_v1(uuid,uuid,uuid,jsonb,uuid)','execute'),'anon cannot persist geocoder package');
select is(public.persist_canonical_bc_geocoder_evidence_v1('00000000-0000-0000-0000-000000003902','00000000-0000-0000-0000-000000003911',(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),'{"provider":"bc_address_geocoder","standardized_address":"475 Main St, Unit 228, Vancouver, BC","returned_address":"475 Main St, Unit 228, Vancouver, BC","province":"BC","locality":"Vancouver","municipality_match":true,"score":100,"precision_points":100,"location_descriptor":"parcelpoint","site_id":"working-gear-475","coordinates":{"latitude":49.28,"longitude":-123.10}}'::jsonb,'00000000-0000-0000-0000-000000003901')->>'outcome','exact_bc_geocoder_persisted','exact BC geocoder package is persisted only against the run-bound authoritative claim');
select is(public.persist_canonical_bc_geocoder_evidence_v1('00000000-0000-0000-0000-000000003902','00000000-0000-0000-0000-000000003911',(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),'{"provider":"bc_address_geocoder","standardized_address":"475 Main St, Unit 228, Vancouver, BC","returned_address":"475 Main St, Unit 228, Vancouver, BC","province":"BC","locality":"Vancouver","municipality_match":true,"score":100,"precision_points":100,"location_descriptor":"parcelpoint","site_id":"working-gear-475","coordinates":{"latitude":49.28,"longitude":-123.10}}'::jsonb,'00000000-0000-0000-0000-000000003901')->>'outcome','exact_bc_geocoder_persisted','geocoder persistence is idempotent');
select is((select count(*)::integer from public.resource_fact_evidence where source_type='bc_geocoder' and claim_id=(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911')),1,'exact package is not duplicated');
select throws_ok($$select public.persist_canonical_bc_geocoder_evidence_v1('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003911',(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),'{}'::jsonb,'00000000-0000-0000-0000-000000003901')$$,null,'reserved or confirmed canonical research item required','wrong run cannot persist a geocoder package');
select is((public.create_machine_initial_location_qc_from_evidence('00000000-0000-0000-0000-000000003911',(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'),(select id from public.resource_fact_evidence where source_type='bc_geocoder' and claim_id=(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911')),'00000000-0000-0000-0000-000000003901')).origin,'machine_initial','exact persisted package feeds server-derived machine QC');
select is(public.dry_run_map_auto_publish_v1('00000000-0000-0000-0000-000000003911',1,(select claim_id from public.canonical_authoritative_research_run_items where run_id='00000000-0000-0000-0000-000000003902' and resource_id='00000000-0000-0000-0000-000000003911'))->>'decision','auto_publish_eligible','corrected current state reaches policy dry run without publication');

select public.begin_canonical_authoritative_research_run('00000000-0000-0000-0000-000000003903',4,'00000000-0000-0000-0000-000000003901');
select public.reserve_canonical_authoritative_research_item('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003912','00000000-0000-0000-0000-000000003901');
select throws_ok($$select public.persist_canonical_authoritative_location_evidence_v1('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003912','https://www.fraserhealth.ca/programs','dudes','DUDES Club operates at 1318 Frances Street, Vancouver.','1318 Frances Street, Vancouver, BC','00000000-0000-0000-0000-000000003901')$$,null,'exact programme-at-site support is required','parent-only DUDES evidence cannot establish neXup occupancy');
select public.reserve_canonical_authoritative_research_item('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003913','00000000-0000-0000-0000-000000003901');
select throws_ok($$select public.persist_canonical_authoritative_location_evidence_v1('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003913','https://example.org','protected','Protected Transition House at 10 Main Street','10 Main Street, Vancouver, BC','00000000-0000-0000-0000-000000003901')$$,null,'sensitive or protected resource cannot persist public occupancy evidence','protected resources fail closed');

select public.reserve_canonical_authoritative_research_item('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003914','00000000-0000-0000-0000-000000003901');
insert into public.resource_fact_claims(id,resource_id,field_name,proposed_value,risk,recommendation,confidence,engine_version,status,claim_fingerprint) values
 ('00000000-0000-0000-0000-000000003931','00000000-0000-0000-0000-000000003914','location_occupancy','"100 Main Street, Surrey, BC"','medium','human_review','high','fixture','observed',repeat('b',64)),
 ('00000000-0000-0000-0000-000000003932','00000000-0000-0000-0000-000000003914','location_occupancy','"100 Main Street, Surrey, BC"','medium','human_review','high','fixture','observed',repeat('c',64));
insert into public.resource_fact_evidence(id,claim_id,source_type,source_url,source_authority,extraction_method,independent_key,evidence_fingerprint) values ('00000000-0000-0000-0000-000000003941','00000000-0000-0000-0000-000000003931','official_provider','https://reuseclinic.example.org',95,'fixture','reuseclinic',repeat('d',64));
select is(public.bind_existing_canonical_authoritative_evidence_v1('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003914','00000000-0000-0000-0000-000000003932','00000000-0000-0000-0000-000000003941','00000000-0000-0000-0000-000000003901')->>'outcome','existing_evidence_rebound','same-resource exact-address evidence is rebound without copying');
select ok(public.canonical_authoritative_evidence_current_v1('00000000-0000-0000-0000-000000003932'),'bound evidence becomes current for target claim');
select is((select count(*)::integer from public.resource_fact_evidence where id='00000000-0000-0000-0000-000000003941'),1,'rebind does not duplicate immutable evidence');
select throws_ok($$select public.finish_canonical_authoritative_research_item('00000000-0000-0000-0000-000000003903','00000000-0000-0000-0000-000000003912','confirmed','wrong','00000000-0000-0000-0000-000000003931','00000000-0000-0000-0000-000000003941','00000000-0000-0000-0000-000000003901')$$,null,'research claim is not bound to resource','run accounting rejects cross-resource claim IDs');
select is((select count(*)::integer from public.resource_locations where public_map),0,'pipeline persistence never publishes');
select set_config('role','postgres',true);
select * from finish(); rollback;
